package com.venture.security;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class PasswordHasherTest {

    private final PasswordHasher hasher = new PasswordHasher();

    /** Generated by the original Node app: crypto.scryptSync(password, salt, 64). */
    private static final String NODE_HASH = "00112233445566778899aabbccddeeff:5699cfee2c5c280e66678242092f368ce88ff05305af2c75a9e629d473deb2165b3797e0e31ec3cda30414573befb697f928384c38b187e8c176107e5be20f01";

    @Test
    void verifiesHashesCreatedByTheOriginalNodeApp() {
        assertTrue(hasher.verify("correct horse battery staple", NODE_HASH));
        assertFalse(hasher.verify("wrong password", NODE_HASH));
    }

    @Test
    void roundTripsItsOwnHashes() {
        String stored = hasher.hash("s3cret-pass");
        assertTrue(hasher.verify("s3cret-pass", stored));
        assertFalse(hasher.verify("s3cret-pasS", stored));
    }

    @Test
    void rejectsMalformedStoredValues() {
        assertFalse(hasher.verify("x", "no-colon-here"));
        assertFalse(hasher.verify("x", "salt:not-hex"));
        assertFalse(hasher.verify("x", null));
    }
}
